class alu_scoreboard extends uvm_scoreboard;
  `uvm_component_utils(alu_scoreboard)
  
  uvm_analysis_imp #(alu_seq_item, alu_scoreboard) ap_imp;

  function new(string name="alu_scoreboard", uvm_component parent=null);
    super.new(name, parent);
    ap_imp = new("ap_imp", this);
  endfunction

  virtual function void write(alu_seq_item item);
    logic [7:0] exp_y;
    logic [3:0] exp_flags;
    logic [8:0] temp_y;

    exp_y = 8'b0;
    exp_flags = 4'b0; // [3] OVF, [2] ZERO, [1] CARRY, [0] SIGN
    temp_y = 9'b0;

    // Independent Reference Model
    case(item.opcode)
      3'b000: begin // ADD
        temp_y = {1'b0, item.a} + {1'b0, item.b};
        exp_y = temp_y[7:0];
        exp_flags[1] = temp_y[8]; // Carry
        exp_flags[3] = (~item.a[7] & ~item.b[7] & exp_y[7]) | (item.a[7] & item.b[7] & ~exp_y[7]); // Overflow
      end
      3'b001: begin // SUB
        temp_y = {1'b0, item.a} + {1'b0, ~item.b} + 8'b1;
        exp_y = temp_y[7:0];
        exp_flags[1] = temp_y[8]; // Sub carry equivalent to (a >= b)
        exp_flags[3] = (item.a[7] & ~item.b[7] & ~exp_y[7]) | (~item.a[7] & item.b[7] & exp_y[7]); // Overflow
      end
      3'b010: exp_y = item.a & item.b; // AND
      3'b011: exp_y = item.a | item.b; // OR
      3'b100: exp_y = item.a ^ item.b; // XOR
      3'b101: exp_y = ~item.a;         // NOT
      3'b110: begin // SHL
        exp_y = item.a << 1;
        exp_flags[1] = item.a[7];
      end
      3'b111: begin // SHR
        exp_y = item.a >> 1;
        exp_flags[1] = item.a[0];
      end
    endcase

    exp_flags[0] = exp_y[7];
    exp_flags[2] = (exp_y == 8'h00);

    if (item.y !== exp_y || item.flags !== exp_flags) begin
      `uvm_error("SB_MISMATCH", $sformatf("OP:%b A:%h B:%h | EXP Y:%h F:%b | ACT Y:%h F:%b",
                 item.opcode, item.a, item.b, exp_y, exp_flags, item.y, item.flags))
    end else begin
      `uvm_info("SB_MATCH", $sformatf("Match! OP:%b A:%h B:%h Y:%h F:%b",
                 item.opcode, item.a, item.b, item.y, item.flags), UVM_HIGH)
    end
  endfunction
endclass

