    cp_flags_ovf: coverpoint pkt.flags[3] { bins set = {1}; bins clr = {0}; }

    cr_opcode_a_b: cross cp_opcode, cp_a, cp_b;
  endgroup

  function new(string name="alu_coverage", uvm_component parent=null);
